-- Drop database, migration 1: foundation (identity, drivers, regions, services).
--
-- Design rules (apply to every later migration too):
--  * Everything lives in schema "app", which Supabase's public Data API does not
--    expose. Only the Cloudflare Worker (via Hyperdrive) talks to this database.
--  * Row Level Security is ON for every table with NO policies, so even if a table
--    were ever exposed by mistake, anon/authenticated users can read nothing.
--  * Primary keys are "generated by default as identity" so the legacy MySQL ids can
--    be imported unchanged (the Flutter apps reference these numeric ids). After the
--    import, sequences are reset (see docs/legacy-db/README.md).
--  * Legacy 0/1 flags (tinyint) become real booleans. The API layer must still send
--    0/1 to the existing apps so they keep working.
--  * Latitude/longitude were text in MySQL; here they are double precision with range
--    checks, plus a generated PostGIS "location" for fast nearest-driver queries.
--  * Email and username are citext, so uniqueness stays case-insensitive like MySQL.
--  * Money-like config uses numeric, never floating point.

create extension if not exists postgis with schema extensions;
create extension if not exists citext with schema extensions;

create schema if not exists app;
revoke all on schema app from public;
alter default privileges in schema app revoke all on tables from public;
alter default privileges in schema app revoke all on sequences from public;
alter default privileges in schema app revoke all on functions from public;

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------
create or replace function app.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- regions (operating areas) and services (ride types with fares)
-- ---------------------------------------------------------------------------
create table app.regions (
  id            bigint generated by default as identity primary key,
  name          text,
  distance_unit text        not null default 'km' check (distance_unit in ('km', 'mile')),
  coordinates   jsonb,                                  -- polygon as drawn in the admin map (legacy format)
  boundary      extensions.geography(Polygon, 4326),    -- same polygon for spatial queries; filled by the API
  status        boolean     not null default true,
  timezone      text        not null default 'UTC',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index regions_boundary_gix on app.regions using gist (boundary);

create table app.services (
  id                 bigint generated by default as identity primary key,
  name               text,
  region_id          bigint      references app.regions (id) on delete cascade,
  capacity           integer     not null default 1,
  base_fare          numeric(14, 4),
  minimum_fare       numeric(14, 4),
  minimum_distance   numeric(14, 4),
  per_distance       numeric(14, 4),
  per_minute_drive   numeric(14, 4),
  per_minute_wait    numeric(14, 4),
  waiting_time_limit numeric(14, 4),
  cancellation_fee   numeric(14, 4),
  payment_method     text        not null default 'cash'
                       check (payment_method in ('cash_wallet', 'cash', 'wallet')),
  commission_type    text        check (commission_type in ('fixed', 'percentage')),
  admin_commission   numeric(14, 4) not null default 0,
  fleet_commission   numeric(14, 4) not null default 0,
  status             boolean     not null default true,
  description        text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index services_region_id_idx on app.services (region_id);

-- ---------------------------------------------------------------------------
-- users (riders, drivers, admins, fleet owners)
-- ---------------------------------------------------------------------------
create table app.users (
  id                      bigint generated by default as identity primary key,
  first_name              text,
  last_name               text,
  display_name            text,
  email                   extensions.citext not null unique,
  username                extensions.citext not null unique,
  password_hash           text        not null,          -- bcrypt ($2y$) imported as-is
  apple_user_identifier   text,
  uid                     text,                          -- Firebase uid (Firestore documents)
  login_type              text        check (login_type in ('app', 'apple', 'google', 'otp')),
  user_type               text        not null check (user_type in ('admin', 'rider', 'driver', 'fleet')),
  status                  text        not null default 'active'
                            check (status in ('active', 'inactive', 'pending', 'reject', 'banned')),
  country_code            text,
  contact_number          text,
  gender                  text        check (gender in ('male', 'female', 'other')),
  address                 text,
  timezone                text        not null default 'UTC',
  email_verified_at       timestamptz,
  -- one-time code: only a hash is stored, never the code itself
  otp_hash                text,
  otp_expires_at          timestamptz,
  otp_verify_at           timestamptz,
  -- push notification identifiers
  player_id               text,                          -- OneSignal
  fcm_token               text,
  app_version             text,
  -- driver / fleet relations
  service_id              bigint      references app.services (id) on delete set null,
  fleet_id                bigint      references app.users (id) on delete set null,
  -- live state
  is_online               boolean     not null default false,
  is_available            boolean     not null default true,
  is_verified_driver      boolean     not null default false,
  latitude                double precision check (latitude between -90 and 90),
  longitude               double precision check (longitude between -180 and 180),
  location                extensions.geography(Point, 4326) generated always as (
                            case when latitude is not null and longitude is not null
                                 then extensions.st_setsrid(extensions.st_makepoint(longitude, latitude), 4326)::extensions.geography
                            end
                          ) stored,
  current_heading         double precision,
  last_location_update_at timestamptz,
  last_actived_at         timestamptz,
  last_notification_seen  timestamptz,
  -- growth
  total_coins             integer     not null default 0,
  referral_code           text,
  partner_referral_code   text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  deleted_at              timestamptz
);
create index users_type_status_idx          on app.users (user_type, status) where deleted_at is null;
create index users_driver_availability_idx  on app.users (is_online, is_available)
  where user_type = 'driver' and deleted_at is null;
create index users_driver_location_gix      on app.users using gist (location)
  where user_type = 'driver' and deleted_at is null;
create index users_player_id_idx            on app.users (player_id) where player_id is not null;
create index users_uid_idx                  on app.users (uid) where uid is not null;
create index users_referral_code_idx        on app.users (referral_code) where referral_code is not null;
create index users_last_location_update_idx on app.users (last_location_update_at);
create index users_service_id_idx           on app.users (service_id);
create index users_fleet_id_idx             on app.users (fleet_id);

create table app.user_details (
  id                  bigint generated by default as identity primary key,
  user_id             bigint      references app.users (id) on delete cascade,
  car_model           text,
  car_color           text,
  car_plate_number    text,
  car_production_year text,
  work_address        text,
  home_address        text,
  work_latitude       double precision,
  work_longitude      double precision,
  home_latitude       double precision,
  home_longitude      double precision,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index user_details_user_id_idx on app.user_details (user_id);

create table app.user_bank_accounts (
  id                  bigint generated by default as identity primary key,
  user_id             bigint      references app.users (id) on delete cascade,
  bank_name           text,
  bank_code           text,
  account_holder_name text,
  account_number      text,
  bank_address        text,
  routing_number      text,
  bank_iban           text,
  bank_swift          text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index user_bank_accounts_user_id_idx on app.user_bank_accounts (user_id);

-- ---------------------------------------------------------------------------
-- authentication
-- ---------------------------------------------------------------------------
-- Replaces Laravel Sanctum's personal_access_tokens. Sanctum stores sha256(secret)
-- and hands the client "<id>|<secret>"; keeping that exact scheme means imported
-- tokens still work and users stay signed in after the cutover.
create table app.api_tokens (
  id           bigint generated by default as identity primary key,
  user_id      bigint      not null references app.users (id) on delete cascade,
  name         text        not null,
  token_hash   text        not null unique,
  abilities    jsonb       not null default '["*"]'::jsonb,
  expires_at   timestamptz,
  last_used_at timestamptz,
  created_at   timestamptz not null default now()
);
create index api_tokens_user_id_idx on app.api_tokens (user_id);

create table app.password_reset_tokens (
  id         bigint generated by default as identity primary key,
  email      extensions.citext not null,
  token_hash text        not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '1 hour'
);
create index password_reset_tokens_email_idx on app.password_reset_tokens (email);

-- ---------------------------------------------------------------------------
-- driver onboarding
-- ---------------------------------------------------------------------------
create table app.documents (
  id              bigint generated by default as identity primary key,
  name            text,
  type            text        not null default 'driver',
  is_required     boolean     not null default false,
  has_expiry_date boolean     not null default false,
  status          boolean     not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- The uploaded files themselves (legacy: spatie "media" table) arrive with the R2
-- file-storage migration.
create table app.driver_documents (
  id               bigint generated by default as identity primary key,
  document_id      bigint      references app.documents (id) on delete cascade,
  driver_id        bigint      references app.users (id) on delete cascade,
  expire_date      date,
  is_verified      smallint    not null default 0 check (is_verified in (0, 1, 2)),  -- 0 pending, 1 approved, 2 rejected
  reminder_sent    boolean     not null default false,
  reminder_sent_at timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index driver_documents_driver_id_idx   on app.driver_documents (driver_id);
create index driver_documents_document_id_idx on app.driver_documents (document_id);

create table app.driver_services (
  id         bigint generated by default as identity primary key,
  driver_id  bigint      references app.users (id) on delete cascade,
  service_id bigint      references app.services (id) on delete cascade,
  status     boolean     not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index driver_services_driver_id_idx  on app.driver_services (driver_id);
create index driver_services_service_id_idx on app.driver_services (service_id);

-- ---------------------------------------------------------------------------
-- triggers + row level security (deny by default, no policies)
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'regions', 'services', 'users', 'user_details', 'user_bank_accounts',
    'documents', 'driver_documents', 'driver_services'
  ] loop
    execute format(
      'create trigger %I before update on app.%I for each row execute function app.touch_updated_at()',
      t || '_touch_updated_at', t);
  end loop;

  foreach t in array array[
    'regions', 'services', 'users', 'user_details', 'user_bank_accounts',
    'api_tokens', 'password_reset_tokens',
    'documents', 'driver_documents', 'driver_services'
  ] loop
    execute format('alter table app.%I enable row level security', t);
  end loop;
end
$$;
